package bo.com.ganadero.sanidad.api;import bo.com.ganadero.sanidad.application.ConfirmarJornadaCommand;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.LocalDate;import java.util.UUID;
public record ConfirmarJornadaRequest(@NotNull UUID operationId,@PositiveOrZero long version,@NotNull UUID planItemId,UUID productoId,UUID loteProductoId,@Positive BigDecimal dosis,@Size(max=30)String unidadDosis,@Size(max=60)String viaAdministracion,@NotNull @PastOrPresent LocalDate fechaAplicacion,@Size(max=60)String resultado,@Size(max=1000)String observaciones){ConfirmarJornadaCommand command(){return new ConfirmarJornadaCommand(operationId,version,planItemId,productoId,loteProductoId,dosis,unidadDosis,viaAdministracion,fechaAplicacion,resultado,observaciones);}}
